import { test, expect } from '@playwright/test';

test.describe('PDF Inline Viewer', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display PDF upload input field', async ({ page }) => {
    const fileInput = page.getByLabel(/upload pdf/i);
    await expect(fileInput).toBeVisible();
  });

  test('should display uploaded PDF in inline viewer', async ({ page }) => {
    const fileInput = page.getByLabel(/upload pdf/i);

    await fileInput.setInputFiles({
      name: 'sample.pdf',
      mimeType: 'application/pdf',
      buffer: Buffer.from('%PDF-1.4\n%test pdf content'),
    });

    const pdfViewer = page.getByRole('region', { name: /pdf viewer/i });
    await expect(pdfViewer).toBeVisible();
  });

  test('should display PDF content after successful upload', async ({ page }) => {
    const fileInput = page.getByLabel(/upload pdf/i);

    await fileInput.setInputFiles({
      name: 'document.pdf',
      mimeType: 'application/pdf',
      buffer: Buffer.from('%PDF-1.4\n%test pdf document'),
    });

    const pdfFrame = page.frameLocator('iframe[title*="PDF"]').first();
    await expect(pdfFrame).toBeVisible();
  });

  test('should show error message for invalid file type', async ({ page }) => {
    const fileInput = page.getByLabel(/upload pdf/i);

    await fileInput.setInputFiles({
      name: 'document.txt',
      mimeType: 'text/plain',
      buffer: Buffer.from('This is not a PDF'),
    });

    const errorMessage = page.getByText(/invalid file type|only pdf files/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should clear viewer when new PDF is uploaded', async ({ page }) => {
    const fileInput = page.getByLabel(/upload pdf/i);

    await fileInput.setInputFiles({
      name: 'first.pdf',
      mimeType: 'application/pdf',
      buffer: Buffer.from('%PDF-1.4\n%first document'),
    });

    const pdfViewer = page.getByRole('region', { name: /pdf viewer/i });
    await expect(pdfViewer).toBeVisible();

    await fileInput.setInputFiles({
      name: 'second.pdf',
      mimeType: 'application/pdf',
      buffer: Buffer.from('%PDF-1.4\n%second document'),
    });

    await expect(pdfViewer).toBeVisible();
  });
});
